const items = $input.all();
if (items.length !== 1) {
  throw new Error('Expected one Daily Brief build response.');
}

const { brief, from } = items[0].json;
if (
  brief?.version !== 'v2' ||
  brief.dry_run !== false ||
  ((brief.verification_status !== undefined || brief.ready_to_send !== undefined) &&
    brief.ready_to_send !== true)
) {
  throw new Error('The Daily Brief build is not ready to send.');
}

const address = /^[a-z0-9.!#$%&'*+/=?^_{|}~-]+@[a-z0-9.-]+$/i;
const recipients = typeof brief.to === 'string' ? brief.to.split(',').map(value => value.trim()) : [];
if (typeof from !== 'string' || !address.test(from) || !recipients.length || !recipients.every(value => address.test(value))) {
  throw new Error('Enter a Gmail sender and comma-separated recipient email addresses.');
}
if (typeof brief.subject !== 'string' || !brief.subject.trim() || /[\r\n]/.test(brief.subject)) {
  throw new Error('The Daily Brief subject must be a single line.');
}
if (typeof brief.text !== 'string' || !brief.text || typeof brief.html !== 'string' || !brief.html) {
  throw new Error('The Daily Brief requires both text and HTML bodies.');
}
if (brief.amp_html != null && typeof brief.amp_html !== 'string') {
  throw new Error('The AMP body must be HTML text.');
}

const parts = [['text/plain', brief.text]];
if (brief.amp_html) {
  parts.push(['text/x-amp-html', brief.amp_html]);
}
parts.push(['text/html', brief.html]);

// Fold UTF-8 encoded words without cutting a Unicode character in half.
const subjectWords = [];
let subjectChunk = '';
for (const character of brief.subject) {
  if (Buffer.byteLength(subjectChunk + character) > 42) {
    subjectWords.push(subjectChunk);
    subjectChunk = '';
  }
  subjectChunk += character;
}
subjectWords.push(subjectChunk);
const subject = subjectWords.map(word => '=?UTF-8?B?' + Buffer.from(word).toString('base64') + '?=').join('\r\n ');

// MIME bodies are base64, so the hyphens in the boundary cannot match body content.
const boundary = 'bianca-daily-brief';
const message = [
  'From: ' + from,
  'To: ' + recipients.join(',\r\n '),
  'Subject: ' + subject,
  'Date: ' + new Date().toUTCString().replace(/GMT$/, '+0000'),
  'MIME-Version: 1.0',
  'Content-Type: multipart/alternative; boundary="' + boundary + '"',
  '',
];
for (const [contentType, body] of parts) {
  const encoded = Buffer.from(body.replace(/\r\n|\r|\n/g, '\r\n')).toString('base64');
  message.push(
    '--' + boundary,
    'Content-Type: ' + contentType + '; charset=UTF-8',
    'Content-Transfer-Encoding: base64',
    '',
    encoded.match(/.{1,76}/g).join('\r\n'),
  );
}
message.push('--' + boundary + '--', '');

return [{ json: { raw: Buffer.from(message.join('\r\n')).toString('base64url') } }];
